   if(resolved.kind==='unverifiable'){setError('This payment\'s deposit-order deadline could not be verified in this browser (a saved record is missing, corrupted, or for a different payment). Nothing was sent. Recover the order in the conversion panel before retrying.');return;}
   if(resolved.kind==='bound'&&Date.now()>=resolved.meta.expiresAt){setError('This deposit order expired while the review was open. Recover the order in the conversion panel; nothing was sent.');return;}
